-- New syllabus edition for this career.
insert into public.syllabus_editions (contest_name,role_name,contest_year)
select 'Polícia Federal','Escrivão de Polícia Federal',2025
where not exists (
  select 1 from public.syllabus_editions
  where contest_name='Polícia Federal' and role_name='Escrivão de Polícia Federal' and contest_year=2025
);

-- Discipline breakdown derived from the provas' own command blocks and
-- section headers: Língua Portuguesa (1-8), Redação Oficial (9-10), Direito
-- Administrativo (11-16), Direitos e Garantias Fundamentais (17-18), Direito
-- Constitucional (19-22, segurança pública/meio ambiente/terras indígenas),
-- Direito Penal (23-25, 28), Direito Processual Penal (26-27), Direitos
-- Humanos (29-32, Regras de Mandela), Direito Internacional (33-34,
-- refugiados e tortura), Legislação Especial (35-44, ECA, segurança
-- privada, Lei de Migração, drogas, tortura, identificação civil, PF,
-- crimes ambientais, Estatuto do Desarmamento), Estatística e Probabilidade
-- (45-52) e Raciocínio Lógico (53-60) no bloco CB2; Informática (61-96,
-- Internet/intranet, redes, segurança da informação, computação em nuvem,
-- teoria geral de sistemas, banco de dados, biometria/FPIR-FNIR, Python,
-- machine learning e API) no bloco CG1; e, na prova específica do cargo,
-- Contabilidade Geral (97-110, fatos administrativos, escrituração,
-- demonstrações contábeis e normatização) e Arquivologia (111-120,
-- princípios, gestão e instrumentos de avaliação de documentos).
with edition as (
  select id from public.syllabus_editions
  where contest_name='Polícia Federal' and role_name='Escrivão de Polícia Federal' and contest_year=2025
)
insert into public.syllabus_topics (edition_id,block_name,discipline,topic_order,topic_text,content_status)
select edition.id,'Prova objetiva',d.discipline,1,d.topic_text,'current'
from edition cross join (values
  ('Língua Portuguesa','Compreensão e interpretação de textos; tipologia textual; aspectos linguísticos: coesão e coerência, morfossintaxe, reescrita de frases e pontuação.'),
  ('Redação Oficial','Manual de Redação da Presidência da República: impessoalidade dos expedientes oficiais e pronomes de tratamento.'),
  ('Direito Administrativo','Atributos dos atos administrativos, responsabilidade civil do Estado, empresas públicas e sociedades de economia mista, regime disciplinar do servidor público, inexigibilidade de licitação e princípio da razoabilidade.'),
  ('Direitos e Garantias Fundamentais','Sigilo das comunicações e restrições por determinação judicial; forma e sistema de governo.'),
  ('Direito Constitucional','Competência constitucional da Polícia Federal e da Polícia Rodoviária Federal (art. 144 da CF), responsabilidade penal da pessoa jurídica por crimes ambientais e pesquisa e lavra de minerais em terras indígenas.'),
  ('Direito Penal','Crime de prevaricação, causas de aumento de pena no roubo, qualificadora da escalada no furto e aplicação da lei penal no espaço.'),
  ('Direito Processual Penal','Instauração do inquérito policial e legitimidade para seu requerimento.'),
  ('Direitos Humanos','Regras de Mandela: registro de bens do recluso, trabalho disciplinar, separação de categorias de presos e direito de recorrer da sentença condenatória.'),
  ('Direito Internacional','Convenção contra a Tortura (extradição por crimes de tortura) e Convenção Relativa ao Estatuto dos Refugiados (não expulsão).'),
  ('Legislação Especial','Estatuto da Criança e do Adolescente, segurança privada, Lei de Migração, Lei de Drogas, Lei de Tortura, identificação civil (Lei n.º 14.967/2024), competência da Polícia Federal sobre crimes cibernéticos, Estatuto do Desarmamento e crimes ambientais.'),
  ('Estatística e Probabilidade','Distribuição normal, soma de variáveis aleatórias, correlação de Pearson, regressão linear simples e intervalo de confiança.'),
  ('Raciocínio Lógico','Tabelas-verdade, lógica de argumentação, proposições condicionais, conjuntos e princípio da inclusão-exclusão.'),
  ('Informática','Internet e intranet, redes de computadores, segurança da informação, computação em nuvem, teoria geral de sistemas, banco de dados relacional e modelo entidade-relacionamento, mineração de dados e Big Data, biometria (FPIR/FNIR), transmissão de dados, modelo OSI, linguagem Python, DNS, autenticação multifator, machine learning e API.'),
  ('Contabilidade Geral','Fatos administrativos permutativos e modificativos, regimes de escrituração (caixa e competência), livro-razão, demonstração de resultado do exercício, impostos diferidos, balancete de verificação, características qualitativas da informação contábil, provisões e Lei das Sociedades por Ações (Lei n.º 6.404/1976).'),
  ('Arquivologia','Sistema de Gestão de Documentos e Arquivos (SIGA), princípios da proveniência e da pertinência, Comissão Permanente de Avaliação de Documentos, NOBRADE, tramitação, gestão arquivística de documentos, fases da gestão documental e instrumentos de avaliação.')
) d(discipline,topic_text)
on conflict (edition_id,discipline,topic_order) do update set topic_text=excluded.topic_text;

with imported(exam_year,item_number,subject,question_text,raw_extraction,official_answer,source_page,content_status,legal_review_required,context_review_required,review_note) as (values
(2025,1,$q$Língua Portuguesa$q$,$q$O texto sugere que o gênero policial é o preferido do público na literatura, na televisão e no cinema.$q$,$q$O texto sugere que o gênero policial é o preferido do público na literatura, na televisão e no cinema.$q$,'E',1,'under_review',true,false,$q$Transcrição verbatim do caderno de provas Escrivão de Polícia Federal (PF 2025, CEBRASPE, Edital nº 1 – PF – Policial, de 20/05/2025, aplicação 27/07/2025); gabarito conferido em 106_PF_25_GabaritosDefinitivos.xlsm. Base legal ainda não conferida individualmente no planalto.gov.br — aguardando revisão item a item antes de content_status=active.$q$),
(2025,2,$q$Língua Portuguesa$q$,$q$Entende-se da leitura do texto que a frequente transposição da narrativa de best-sellers para as telas da televisão e do cinema se justifica pela expectativa de repetição do sucesso obtido na venda das respectivas obras literárias.$q$,$q$Entende-se da leitura do texto que a frequente transposição da narrativa de best-sellers para as telas da televisão e do cinema se justifica pela expectativa de repetição do sucesso obtido na venda das respectivas obras literárias.$q$,'E',1,'under_review',true,false,$q$Transcrição verbatim do caderno de provas Escrivão de Polícia Federal (PF 2025, CEBRASPE, Edital nº 1 – PF – Policial, de 20/05/2025, aplicação 27/07/2025); gabarito conferido em 106_PF_25_GabaritosDefinitivos.xlsm. Base legal ainda não conferida individualmente no planalto.gov.br — aguardando revisão item a item antes de content_status=active.$q$),
(2025,3,$q$Língua Portuguesa$q$,$q$A partir das ideias de Carlos Gerbase reproduzidas no texto, conclui-se que as histórias narradas em livros e filmes podem nortear a conduta social de leitores e espectadores.$q$,$q$A partir das ideias de Carlos Gerbase reproduzidas no texto, conclui-se que as histórias narradas em livros e filmes podem nortear a conduta social de leitores e espectadores.$q$,'C',1,'under_review',true,false,$q$Transcrição verbatim do caderno de provas Escrivão de Polícia Federal (PF 2025, CEBRASPE, Edital nº 1 – PF – Policial, de 20/05/2025, aplicação 27/07/2025); gabarito conferido em 106_PF_25_GabaritosDefinitivos.xlsm. Base legal ainda não conferida individualmente no planalto.gov.br — aguardando revisão item a item antes de content_status=active.$q$),
(2025,4,$q$Língua Portuguesa$q$,$q$O termo "crescente" (segundo período do primeiro parágrafo) poderia ser substituído, sem prejuízo do sentido original do texto, por considerável.$q$,$q$O termo "crescente" (segundo período do primeiro parágrafo) poderia ser substituído, sem prejuízo do sentido original do texto, por considerável.$q$,'E',1,'under_review',true,false,$q$Transcrição verbatim do caderno de provas Escrivão de Polícia Federal (PF 2025, CEBRASPE, Edital nº 1 – PF – Policial, de 20/05/2025, aplicação 27/07/2025); gabarito conferido em 106_PF_25_GabaritosDefinitivos.xlsm. Base legal ainda não conferida individualmente no planalto.gov.br — aguardando revisão item a item antes de content_status=active.$q$),
(2025,5,$q$Língua Portuguesa$q$,$q$No segundo período do segundo parágrafo, a oração "que as histórias têm começo, meio e fim" classifica-se sintaticamente como subordinada adjetiva restritiva.$q$,$q$No segundo período do segundo parágrafo, a oração "que as histórias têm começo, meio e fim" classifica-se sintaticamente como subordinada adjetiva restritiva.$q$,'E',1,'under_review',true,false,$q$Transcrição verbatim do caderno de provas Escrivão de Polícia Federal (PF 2025, CEBRASPE, Edital nº 1 – PF – Policial, de 20/05/2025, aplicação 27/07/2025); gabarito conferido em 106_PF_25_GabaritosDefinitivos.xlsm. Base legal ainda não conferida individualmente no planalto.gov.br — aguardando revisão item a item antes de content_status=active.$q$),
(2025,6,$q$Língua Portuguesa$q$,$q$A supressão da vírgula empregada após "personagem" (primeiro período do terceiro parágrafo) prejudicaria a correção gramatical do texto.$q$,$q$A supressão da vírgula empregada após "personagem" (primeiro período do terceiro parágrafo) prejudicaria a correção gramatical do texto.$q$,'C',1,'under_review',true,false,$q$Transcrição verbatim do caderno de provas Escrivão de Polícia Federal (PF 2025, CEBRASPE, Edital nº 1 – PF – Policial, de 20/05/2025, aplicação 27/07/2025); gabarito conferido em 106_PF_25_GabaritosDefinitivos.xlsm. Base legal ainda não conferida individualmente no planalto.gov.br — aguardando revisão item a item antes de content_status=active.$q$),
(2025,7,$q$Língua Portuguesa$q$,$q$No segundo parágrafo, o intercambiamento das expressões "Logo" (terceiro período) e "Além disso" (quarto período), embora alterasse as relações coesivas entre os períodos, manteria a coerência das ideias do texto.$q$,$q$No segundo parágrafo, o intercambiamento das expressões "Logo" (terceiro período) e "Além disso" (quarto período), embora alterasse as relações coesivas entre os períodos, manteria a coerência das ideias do texto.$q$,'E',1,'under_review',true,false,$q$Transcrição verbatim do caderno de provas Escrivão de Polícia Federal (PF 2025, CEBRASPE, Edital nº 1 – PF – Policial, de 20/05/2025, aplicação 27/07/2025); gabarito conferido em 106_PF_25_GabaritosDefinitivos.xlsm. Base legal ainda não conferida individualmente no planalto.gov.br — aguardando revisão item a item antes de content_status=active.$q$),
(2025,8,$q$Língua Portuguesa$q$,$q$O pronome presente no termo "nela" (último parágrafo) tem como referente "a narrativa policial".$q$,$q$O pronome presente no termo "nela" (último parágrafo) tem como referente "a narrativa policial".$q$,'C',1,'under_review',true,false,$q$Transcrição verbatim do caderno de provas Escrivão de Polícia Federal (PF 2025, CEBRASPE, Edital nº 1 – PF – Policial, de 20/05/2025, aplicação 27/07/2025); gabarito conferido em 106_PF_25_GabaritosDefinitivos.xlsm. Base legal ainda não conferida individualmente no planalto.gov.br — aguardando revisão item a item antes de content_status=active.$q$),
(2025,9,$q$Redação Oficial$q$,$q$Os assuntos objetos dos expedientes oficiais devem ser tratados de forma estritamente impessoal, uma vez que a redação oficial é elaborada sempre em nome do serviço público e em atendimento ao interesse geral dos cidadãos.$q$,$q$Os assuntos objetos dos expedientes oficiais devem ser tratados de forma estritamente impessoal, uma vez que a redação oficial é elaborada sempre em nome do serviço público e em atendimento ao interesse geral dos cidadãos.$q$,'C',1,'under_review',true,false,$q$Transcrição verbatim do caderno de provas Escrivão de Polícia Federal (PF 2025, CEBRASPE, Edital nº 1 – PF – Policial, de 20/05/2025, aplicação 27/07/2025); gabarito conferido em 106_PF_25_GabaritosDefinitivos.xlsm. Base legal ainda não conferida individualmente no planalto.gov.br — aguardando revisão item a item antes de content_status=active.$q$),
(2025,10,$q$Redação Oficial$q$,$q$Na redação oficial, os pronomes de tratamento são empregados em três contextos: endereçamento, vocativo e corpo do texto.$q$,$q$Na redação oficial, os pronomes de tratamento são empregados em três contextos: endereçamento, vocativo e corpo do texto.$q$,'C',1,'under_review',true,false,$q$Transcrição verbatim do caderno de provas Escrivão de Polícia Federal (PF 2025, CEBRASPE, Edital nº 1 – PF – Policial, de 20/05/2025, aplicação 27/07/2025); gabarito conferido em 106_PF_25_GabaritosDefinitivos.xlsm. Base legal ainda não conferida individualmente no planalto.gov.br — aguardando revisão item a item antes de content_status=active.$q$),
(2025,11,$q$Direito Administrativo$q$,$q$A presunção de veracidade dos atos administrativos refere-se aos fatos, ou seja, presumem-se verdadeiros os fatos alegados pela administração pública, ao passo que a autoexecutoriedade constitui atributo pelo qual os atos administrativos se impõem a terceiros, independentemente de sua concordância.$q$,$q$A presunção de veracidade dos atos administrativos refere-se aos fatos, ou seja, presumem-se verdadeiros os fatos alegados pela administração pública, ao passo que a autoexecutoriedade constitui atributo pelo qual os atos administrativos se impõem a terceiros, independentemente de sua concordância.$q$,'E',1,'under_review',true,false,$q$Transcrição verbatim do caderno de provas Escrivão de Polícia Federal (PF 2025, CEBRASPE, Edital nº 1 – PF – Policial, de 20/05/2025, aplicação 27/07/2025); gabarito conferido em 106_PF_25_GabaritosDefinitivos.xlsm. Base legal ainda não conferida individualmente no planalto.gov.br — aguardando revisão item a item antes de content_status=active.$q$),
(2025,12,$q$Direito Administrativo$q$,$q$A pessoa que sofrer algum dano por ato praticado por um servidor público no exercício da função poderá ajuizar ação de indenização somente contra o Estado.$q$,$q$A pessoa que sofrer algum dano por ato praticado por um servidor público no exercício da função poderá ajuizar ação de indenização somente contra o Estado.$q$,'E',1,'under_review',true,false,$q$Transcrição verbatim do caderno de provas Escrivão de Polícia Federal (PF 2025, CEBRASPE, Edital nº 1 – PF – Policial, de 20/05/2025, aplicação 27/07/2025); gabarito conferido em 106_PF_25_GabaritosDefinitivos.xlsm. Base legal ainda não conferida individualmente no planalto.gov.br — aguardando revisão item a item antes de content_status=active.$q$),
(2025,13,$q$Direito Administrativo$q$,$q$As sociedades de economia mista e as empresas públicas desempenham atividade de natureza econômica e se distinguem pela forma de organização e pela composição do capital.$q$,$q$As sociedades de economia mista e as empresas públicas desempenham atividade de natureza econômica e se distinguem pela forma de organização e pela composição do capital.$q$,'C',1,'under_review',true,false,$q$Transcrição verbatim do caderno de provas Escrivão de Polícia Federal (PF 2025, CEBRASPE, Edital nº 1 – PF – Policial, de 20/05/2025, aplicação 27/07/2025); gabarito conferido em 106_PF_25_GabaritosDefinitivos.xlsm. Base legal ainda não conferida individualmente no planalto.gov.br — aguardando revisão item a item antes de content_status=active.$q$),
(2025,14,$q$Direito Administrativo$q$,$q$O cancelamento do registro da penalidade de suspensão de servidor público, que ocorre após o decurso de dois anos de efetivo exercício, surtirá efeitos retroativos caso o servidor não pratique, nesse período, nova infração disciplinar.$q$,$q$O cancelamento do registro da penalidade de suspensão de servidor público, que ocorre após o decurso de dois anos de efetivo exercício, surtirá efeitos retroativos caso o servidor não pratique, nesse período, nova infração disciplinar.$q$,'E',1,'under_review',true,false,$q$Transcrição verbatim do caderno de provas Escrivão de Polícia Federal (PF 2025, CEBRASPE, Edital nº 1 – PF – Policial, de 20/05/2025, aplicação 27/07/2025); gabarito conferido em 106_PF_25_GabaritosDefinitivos.xlsm. Base legal ainda não conferida individualmente no planalto.gov.br — aguardando revisão item a item antes de content_status=active.$q$),
(2025,15,$q$Direito Administrativo$q$,$q$É inexigível a licitação para a contratação que possa acarretar comprometimento da segurança nacional, nos casos estabelecidos pelo Ministério da Defesa, mediante demanda dos comandos das Forças Armadas.$q$,$q$É inexigível a licitação para a contratação que possa acarretar comprometimento da segurança nacional, nos casos estabelecidos pelo Ministério da Defesa, mediante demanda dos comandos das Forças Armadas.$q$,'E',1,'under_review',true,false,$q$Transcrição verbatim do caderno de provas Escrivão de Polícia Federal (PF 2025, CEBRASPE, Edital nº 1 – PF – Policial, de 20/05/2025, aplicação 27/07/2025); gabarito conferido em 106_PF_25_GabaritosDefinitivos.xlsm. Base legal ainda não conferida individualmente no planalto.gov.br — aguardando revisão item a item antes de content_status=active.$q$),
(2025,16,$q$Direito Administrativo$q$,$q$O princípio da razoabilidade é considerado um princípio implícito da administração pública e se baseia naquilo que se situa dentro de limites aceitáveis.$q$,$q$O princípio da razoabilidade é considerado um princípio implícito da administração pública e se baseia naquilo que se situa dentro de limites aceitáveis.$q$,'C',1,'under_review',true,false,$q$Transcrição verbatim do caderno de provas Escrivão de Polícia Federal (PF 2025, CEBRASPE, Edital nº 1 – PF – Policial, de 20/05/2025, aplicação 27/07/2025); gabarito conferido em 106_PF_25_GabaritosDefinitivos.xlsm. Base legal ainda não conferida individualmente no planalto.gov.br — aguardando revisão item a item antes de content_status=active.$q$),
