(2025,118,$q$Arquivologia$q$,$q$As fases da gestão de documentos dividem-se em corrente, intermediária e permanente.$q$,$q$As fases da gestão de documentos dividem-se em corrente, intermediária e permanente.$q$,'E',1,'under_review',true,false,$q$Transcrição verbatim do caderno de provas Escrivão de Polícia Federal (PF 2025, CEBRASPE, Edital nº 1 – PF – Policial, de 20/05/2025, aplicação 27/07/2025); gabarito conferido em 106_PF_25_GabaritosDefinitivos.xlsm. Base legal ainda não conferida individualmente no planalto.gov.br — aguardando revisão item a item antes de content_status=active.$q$),
(2025,119,$q$Arquivologia$q$,$q$A mensuração dos documentos em suporte de papel é feita por meio do metro linear.$q$,$q$A mensuração dos documentos em suporte de papel é feita por meio do metro linear.$q$,'X',1,'annulled',true,false,$q$Item anulado no gabarito oficial definitivo (106_PF_25_GabaritosDefinitivos.xlsm); não é exibido aos estudantes.$q$),
(2025,120,$q$Arquivologia$q$,$q$Um dos instrumentos de avaliação de documentos é o plano de destinação de documentos.$q$,$q$Um dos instrumentos de avaliação de documentos é o plano de destinação de documentos.$q$,'C',1,'under_review',true,false,$q$Transcrição verbatim do caderno de provas Escrivão de Polícia Federal (PF 2025, CEBRASPE, Edital nº 1 – PF – Policial, de 20/05/2025, aplicação 27/07/2025); gabarito conferido em 106_PF_25_GabaritosDefinitivos.xlsm. Base legal ainda não conferida individualmente no planalto.gov.br — aguardando revisão item a item antes de content_status=active.$q$)), editions as (
  select id,contest_year from public.syllabus_editions
  where contest_name='Polícia Federal' and role_name='Escrivão de Polícia Federal' and contest_year=2025
), sourced as (
  select imported.*,
    case
      when imported.item_number between 1 and 60 then 'Prova objetiva PF 2025 - Conhecimentos Básicos Bloco II (CB2)'
      when imported.item_number between 61 and 96 then 'Prova objetiva PF 2025 - Conhecimentos Básicos Bloco II (CG1) - Informática'
      else 'Prova objetiva PF 2025 - Escrivão de Polícia Federal - Conhecimentos Específicos'
    end as question_source_title,
    case
      when imported.item_number between 1 and 60 then 'Gabarito definitivo PF 2025 - Conhecimentos Básicos Bloco II (CB2)'
      when imported.item_number between 61 and 96 then 'Gabarito definitivo PF 2025 - Conhecimentos Básicos Bloco II (CG1) - Informática'
      else 'Gabarito definitivo PF 2025 - Escrivão de Polícia Federal - Conhecimentos Específicos'
    end as answer_source_title
  from imported
), resolved as (
  select sourced.*, question_source.id question_source_id, answer_source.id answer_key_source_id, topic.id syllabus_topic_id
  from sourced
  join editions on editions.contest_year=sourced.exam_year
  join public.syllabus_topics topic on topic.edition_id=editions.id and topic.discipline=sourced.subject and topic.topic_order=1
  join public.content_sources question_source on question_source.title=sourced.question_source_title
  join public.content_sources answer_source on answer_source.title=sourced.answer_source_title
)
insert into public.official_exam_questions (
  question_source_id,answer_key_source_id,syllabus_topic_id,contest_name,career_name,exam_board,exam_year,item_number,subject,
  question_text,raw_extraction,official_answer,source_page,content_status,legal_review_required,
  context_review_required,review_note
)
select question_source_id,answer_key_source_id,syllabus_topic_id,'Polícia Federal','Escrivão de Polícia Federal','CEBRASPE',exam_year,item_number,subject,
  question_text,raw_extraction,official_answer,source_page,content_status,legal_review_required,
  context_review_required,review_note
from resolved
on conflict (contest_name,career_name,exam_year,item_number) do nothing;
